import {rimProfiles} from './tuning-rims.js?v=0.8.1';
import {TUNING_CATEGORIES,workshopQuote,TUNING_PRICES} from './tuning.js?v=0.8.1';
import {UPGRADE_CATEGORIES,normalizeUpgrades,upgradePrice,vehiclePerformance} from './vehicle-upgrades.js?v=0.8.1';
import {VEHICLES,euro} from './data.js?v=0.8.1';
const rimIcon=(id,type)=>{const style=id==='default'?(type==='sport'?'sport':'classic'):id;return '<svg viewBox="-1.08 -1.08 2.16 2.16" aria-hidden="true"><circle r=".98" fill="#14232b" stroke="#c6d0d0" stroke-width=".055"/>'+rimProfiles(style).map(poly=>'<polygon points="'+poly.map(p=>p.join(',')).join(' ')+'" fill="#adbabc" stroke="#d3dedf" stroke-width=".012"/>').join('')+'<circle r=".16" fill="#71828a" stroke="#bdcbcd" stroke-width=".025"/></svg>';};
const spoilerIcon=id=>'<svg viewBox="0 0 90 60" aria-hidden="true"><path d="M9 40V32L22 28L31 14H57L70 28H80V40Z" fill="#647d82"/><path d="M31 17H54L64 28H24Z" fill="#18313d"/><circle cx="24" cy="41" r="8" fill="#13232c"/><circle cx="67" cy="41" r="8" fill="#13232c"/>'+(id==='lip'?'<path d="M9 30H22" stroke="#dfbf80" stroke-width="4"/>':id==='touring'?'<path d="M11 29V21M20 29V21M5 20H25" stroke="#dfbf80" stroke-width="3"/>':'')+'</svg>';
export function tuningPanel(s,session,button){if(!session)return '<section class="tuning-ui"><p class="lead">Dein Fahrzeug, dein Stil.</p><p>Fahre deinen Kleinwagen, Lieferwagen oder dein Sportcoupé in die markierte Bucht. Folge dem Pfeil, halte an und steige aus. Eine grüne Markierung bestätigt die Ausrichtung.</p><p>Fahrräder können hier nicht angepasst werden.</p>'+button('Zurück','close','','secondary')+'</section>';
 const {vehicle,draft,tab}=session,upgrades=session.upgrades||normalizeUpgrades(vehicle.upgrades),current=normalizeUpgrades(vehicle.upgrades),section=session.section||'power',options=TUNING_CATEGORIES[tab].options,quote=workshopQuote(vehicle,draft,upgrades),performance=vehiclePerformance(vehicle,upgrades),installed=vehiclePerformance(vehicle);
 const sections={power:'LEISTUNG',chassis:'FAHRWERK',tires:'REIFEN',looks:'OPTIK'};
 const bars=Object.entries({acceleration:'Beschleunigung',top:'Höchstgeschwindigkeit',braking:'Bremsen',handling:'Handling'}).map(([key,label])=>{const value=Math.round(performance[key]*100),old=Math.round(installed[key]*100);return '<label class="tuning-stat">'+label+' <span>'+old+' → '+value+' %</span><meter min="0" max="165" value="'+value+'">'+value+' %</meter></label>';}).join('');
 const parts=Object.entries(UPGRADE_CATEGORIES).filter(([,c])=>c.tab===section).map(([key,c])=>'<div class="upgrade-category"><p><b>'+c.name+'</b> · Eingebaut: '+c.options[current[key]].name+'</p><div class="upgrade-options">'+Object.entries(c.options).map(([id,o])=>'<button class="tuning-option '+(upgrades[key]===id?'selected':'')+'" aria-pressed="'+(upgrades[key]===id)+'" data-action="tuningUpgrade" data-arg="'+key+'|'+id+'"><b>'+o.name+'</b><span>'+o.effect+'</span><strong>'+(current[key]===id?'Eingebaut · '+euro(0):euro(upgradePrice(vehicle,key,id)))+'</strong></button>').join('')+'</div></div>').join('');
 const optics=section==='looks'?'<div class="tabs">'+Object.entries(TUNING_CATEGORIES).map(([id,c])=>button(c.label,'tuningTab',id,id===tab?'active':'secondary')).join('')+'</div><p class="footnote">'+TUNING_CATEGORIES[tab].name+' · Eingebaut: '+TUNING_CATEGORIES[tab].options[session.vehicle.customization?.[tab]||({paint:'default',rims:'default',rimColor:'silver',tint:'default',trim:'default',spoiler:'none'}[tab])].name+' · rein optisch</p><div class="tuning-options">'+Object.entries(options).map(([id,o])=>'<button class="tuning-option '+(draft[tab]===id?'selected':'')+'" aria-pressed="'+(draft[tab]===id)+'" data-action="tuningOption" data-arg="'+tab+'|'+id+'">'+(tab==='rims'?rimIcon(id,vehicle.id):tab==='spoiler'?spoilerIcon(id):'<i style="background:#'+(o.color??session.mesh.userData.defaultPaint??0x447c84).toString(16).padStart(6,'0')+'"></i>')+'<span>'+o.name+'</span><small>'+euro(TUNING_PRICES[tab])+'</small></button>').join('')+'</div>':'';
 const changes=quote.changes.map(k=>'<div><span>'+TUNING_CATEGORIES[k].name+'</span><span>'+euro(TUNING_PRICES[k])+'</span></div>').join('')+quote.upgradeChanges.map(k=>'<div><span>'+UPGRADE_CATEGORIES[k].name+'</span><span>'+euro(upgradePrice(vehicle,k,upgrades[k]))+'</span></div>').join('');
 return '<section class="tuning-ui"><p class="tuning-vehicle">DEIN FAHRZEUG · '+VEHICLES[vehicle.id].name+'</p><div class="tabs tuning-sections">'+Object.entries(sections).map(([id,label])=>button(label,'tuningSection',id,section===id?'active':'secondary')).join('')+'</div><div class="tuning-stats">'+bars+'<small>Serie = 100 % · eingebaut → Vorschau</small></div>'+optics+parts+'<div class="tuning-cost"><b>Änderungen</b>'+(changes||'<p>Keine Änderungen</p>')+'</div><p class="footnote">Preis je Einbau inkl. Montage, ohne Rückvergütung. Optik erscheint sofort am Fahrzeug. Fahrwirkung gilt nach Übernehmen.</p><p class="'+(s.money<quote.total?'negative':'')+'">Bargeld · '+euro(s.money)+'</p><footer class="tuning-actions"><div class="button-row">'+button('VORSCHAU','tuningPreview','','secondary')+button('ABBRECHEN','close','','secondary')+'</div>'+button('ÜBERNEHMEN · '+euro(quote.total),'tuningConfirm','','primary',!quote.total||s.money<quote.total)+'</footer></section>';
}
